'SUPABASE_ANON_KEY',
'SUPABASE_SERVICE_ROLE_KEY',
'SITE_URL',
'CORS_ALLOW_ORIGINS',
'RETAIL_CURRENCY',
'PROVIDER_CURRENCY',
'FX_PROVIDER_TO_RETAIL',
'MARKUP_MULTIPLIER',
'RETAIL_CATALOGUE_URL',
'RETAIL_SOCIALPANEL_IDS',
'SOCIALPANEL24_API_KEY',
'SOCIALPANEL24_TIMEOUT_MS',
'SOCIALPANEL24_ENABLED',
'PROVIDER_ENV',
'STRIPE_SECRET_KEY',
'STRIPE_WEBHOOK_SECRET',
