refreshed: false,
providerError: 'empty_provider_catalogue',
providerCount: 0,
cacheKeys: [],
visible: 0,
purchasable: 0,
unmapped: 0,
missing: 0,
products: [],
};
}
const built = await buildCatalogue(env, deps);
const payload = {
ok: true,
data: built.publicServices,
generatedAt: new Date(now).toISOString(),
ttlSeconds: Math.round(CATALOGUE_TTL_MS / 1000),
};
const entry = {
expires: now + CATALOGUE_TTL_MS,
staleUntil: now + CATALOGUE_STALE_MS,
payload,
};
const purchasableCount = countPurchasableRows(built.publicServices);
let priorEntry = null;
if (deps.cacheGet) {
priorEntry = await deps.cacheGet('catalogue:public');
}
const priorPurchasable = countPurchasableRows(priorEntry?.payload?.data);
const skipPublicCache = purchasableCount === 0 && priorPurchasable > 0;
